// visca catalogo con sesion iniciada
import React from 'react';
import { Link } from 'react-router-dom';
//estilos
import "../../components/cliente.css";
//imagenes

// header y footer
import Header from '../../components/Header_c.jsx'; 
import Footer from '../../components/Footer.jsx';

const Catalogo_c = () => {
    return (
    <>
    <Header />

    <main>
        <section className="contenido-inicio">
            <h1>Catálogo de productos</h1>  
            <p>Explora nuestros productos tejidos a mano, hechos con amor y dedicación</p>

            <div className="contenedor-productos">

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 1*/}
                    <p>Virgencitas de crochet de 20 CM</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 2*/}
                    <p>Ramo de tulipanes tejidos</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 3*/}
                    <p>Cubrelecho español</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 4*/}
                    <p>Amigurumi Stitch</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 5*/}
                    <p>Amigurumi perrito</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 6*/}
                    <p>Accesorios para maleta</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 7*/}
                    <p>Llavero tejido hollow knight</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 8*/}
                    <p>Sábanas para cama doble</p>
                </div>
                {/*Cierre del link*/}


                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 9*/}
                    <p>Perritos snoopy para pareja</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 10*/}
                    <p>Llavero corazón tejido</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 11*/}
                    <p>Tulipanes rosas tejidos</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 12*/}
                    <p>Llaveros pokebolas</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 13*/}
                    <p>Mini pingüinos de crochet</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 14*/}
                    <p>Reno navideño tejido</p>
                </div>
                {/*Cierre del link*/}

                {/*link del js de productos*/}
                <div className="producto">
                    {/*imagen del producto 15*/}
                    <p>Amigurumi capitan america</p>
                </div>
                {/*Cierre del link*/}

            </div>
        </section>
    </main>

    <Footer />
    </>
    );
    };

    export default Catalogo_c;
